import { resolve } from 'node:path'
import { buildSessionContext, SessionManager } from '@earendil-works/pi-coding-agent'
import { describe, expect, it } from 'vitest'

/**
 * pi-web JSONL compat test (per Q5 + plan §1C.7):
 *
 * Verify evo-pi can read a JSONL file generated by pi-web (in production use).
 *
 * Why this matters:
 * - SDK SessionManager.open() parses JSONL header + entries
 * - If format drift happens (e.g., pi-web adds new fields we don't know
 *   about), this test catches it before production
 * - Confirms CURRENT_SESSION_VERSION=3 compat
 *
 * Source: `/home/berton/.pi/agent/sessions/--home-berton--/2026-10-11...jsonl`
 * (real pi-web generated session from user machine; copied here for fixture)
 */

const FIXTURE_PATH = resolve(__dirname, './pi-web-real.jsonl')

describe('pi-web JSONL compat (Q5 verification)', () => {
  it('SDK SessionManager.open() parses real pi-web JSONL without error', () => {
    expect(() => SessionManager.open(FIXTURE_PATH)).not.toThrow()
  })

  it('returns valid SessionInfo with header fields', () => {
    const manager = SessionManager.open(FIXTURE_PATH)
    const header = manager.getHeader()
    expect(header).not.toBeNull()
    expect(header?.id).toBe('01a12854-3ddd-75f1-af45-a4aa4b933c42')
    expect(header?.cwd).toBe('/home/berton')
    expect(header?.version).toBe(3) // CURRENT_SESSION_VERSION
  })

  it('exposes SessionInfo-compatible shape via getters', () => {
    const manager = SessionManager.open(FIXTURE_PATH)
    expect(manager.getSessionId()).toBe('01a12854-3ddd-75f1-af45-a4aa4b933c42')
    expect(manager.getCwd()).toBe('/home/berton')
    expect(manager.getEntryCount()).toBeGreaterThan(0)
  })

  it('JSONL has at least 1 message entry', () => {
    const manager = SessionManager.open(FIXTURE_PATH)
    const entries = manager.getEntries()
    const messageEntries = entries.filter((e) => e.type === 'message')
    expect(messageEntries.length).toBeGreaterThan(0)
  })

  it('message entries have role + content shape (lenient — covers all AgentMessage variants)', () => {
    const manager = SessionManager.open(FIXTURE_PATH)
    const entries = manager.getEntries()
    const firstMsg = entries.find((e) => e.type === 'message')
    expect(firstMsg).toBeDefined()
    if (firstMsg && firstMsg.type === 'message') {
      // AgentMessage is a discriminated union; narrow via role check
      const msg = firstMsg.message
      // All AgentMessage variants have a role field (per SDK invariant)
      expect(typeof msg.role).toBe('string')
      // Compatibility check: any content-bearing field exists
      // (some variants have .content, others .command/.output etc.)
      const hasAnyContentField =
        'content' in msg || 'command' in msg || 'output' in msg || 'thought' in msg
      expect(hasAnyContentField).toBe(true)
    }
  })
})

// ---------------------------------------------------------------------------
// Phase 2 PR.C 2C.10: read-side compat verification
// ---------------------------------------------------------------------------
// Adds 3 assertions for the read-side use-case path:
//   1. buildSessionContext(entries) returns a valid 3-field SessionContext
//   2. getTree() returns a non-empty SessionTreeNode[] (for chained sessions)
//   3. All message entries have valid shape per SDK SessionMessageEntry
//
// Goal: catch compat regressions in the read-side path (per plan §2C.10)
// before PR.D 2D.3 pi-web roundtrip merge.

describe('pi-web JSONL compat — read-side (PR.C 2C.10)', () => {
  it('buildSessionContext(entries) returns valid 3-field SessionContext', () => {
    const manager = SessionManager.open(FIXTURE_PATH)
    const entries = manager.getEntries()
    const ctx = buildSessionContext(entries)
    // SDK SessionContext has 3 fields; evo-pi extends to 6 in domain/types.ts
    expect(ctx.messages).toBeDefined()
    expect(Array.isArray(ctx.messages)).toBe(true)
    expect(ctx.messages.length).toBeGreaterThan(0)
    expect(typeof ctx.thinkingLevel).toBe('string')
    expect(ctx.model === null || typeof ctx.model === 'object').toBe(true)
  })

  it('getTree() returns non-empty SessionTreeNode[] (for chained sessions)', () => {
    const manager = SessionManager.open(FIXTURE_PATH)
    const tree = manager.getTree()
    expect(Array.isArray(tree)).toBe(true)
    expect(tree.length).toBeGreaterThan(0)
    // Each node has entry + children per SDK contract
    expect(tree[0]?.entry).toBeDefined()
    expect(Array.isArray(tree[0]?.children)).toBe(true)
  })

  it('all message entries have valid SDK SessionMessageEntry shape', () => {
    const manager = SessionManager.open(FIXTURE_PATH)
    const entries = manager.getEntries()
    const messageEntries = entries.filter(
      (e): e is Extract<(typeof entries)[number], { type: 'message' }> => e.type === 'message',
    )
    expect(messageEntries.length).toBeGreaterThan(0)
    for (const entry of messageEntries) {
      // SessionMessageEntry shape: type='message' + id + parentId + timestamp + message
      expect(entry.type).toBe('message')
      expect(typeof entry.id).toBe('string')
      expect(entry.id.length).toBeGreaterThan(0)
      // parentId can be null (root) or string
      expect(entry.parentId === null || typeof entry.parentId === 'string').toBe(true)
      expect(typeof entry.timestamp).toBe('string')
      // entry.message is an AgentMessage (any role)
      expect(entry.message).toBeDefined()
      expect(typeof (entry.message as { role: unknown }).role).toBe('string')
    }
  })
})
